<!DOCTYPE html>
<html>
<head>
<title>Maze Game</title>
<style>
body {
  font-family: sans-serif;
}

#maze {
  border: 1px solid black;
}

canvas {
  display: block;
}
</style>
</head>
<body>
  <h1>Maze Game</h1>
  <div id="maze"></div>
  <p>Completed: <span id="completed">0</span></p>
  <p>Timer: <span id="timer">0</span></p>
  <button id="reset">Reset Maze</button>

<script>
const canvasWidth = 800;
const canvasHeight = 600;
const cellSize = 20;
const numBots = 24;

let mazeCanvas, ctx;
let mazeData; // 2D array representing the maze (walls)
let bots = [];
let timer = 0;
let completedCount = 0;
let gameRunning = true;

function initializeMaze() {
  canvas = document.createElement('canvas');
  canvas.width = canvasWidth;
  canvas.height = canvasHeight;
  ctx = canvas.getContext('2d');
  document.getElementById('maze').appendChild(canvas);

  // Generate a random maze (simple recursive backtracker)
  mazeData = generateMaze();

  bots = [];
  for (let i = 0; i < numBots; i++) {
    const bot = createBot();
    bots.push(bot);
  }

  resetTimer();
}

function generateMaze() {
  const rows = 20;
  const cols = 30;
  const maze = Array(rows).fill(null).map(() => Array(cols).fill(1)); // 1=wall, 0=path

  function carvePath(r, c) {
    maze[r][c] = 0;
    const directions = [[0, 2], [2, 0], [0, -2], [-2, 0]];
    directions.sort(() => Math.random() - 0.5); // Randomize direction order

    for (const [dr, dc] of directions) {
      const nr = r + dr;
      const nc = c + dc;
      if (nr > 0 && nr < rows - 1 && nc > 0 && nc < cols - 1 && maze[nr][nc] === 1) {
        maze[r + dr / 2][c + dc / 2] = 0; // Carve passage
        carvePath(nr, nc);
      }
    }
  }

  carvePath(1, 1);
  return maze;
}


function createBot() {
  const r = Math.floor(Math.random() * (mazeData.length - 2)) + 1;
  const c = Math.floor(Math.random() * (mazeData[0].length - 2)) + 1;

  return {
    r: r,
    c: c,
    path: [{r, c}],
    deadEnds: [],
    finishTick: null,
  };
}



function drawMaze() {
  ctx.fillStyle = 'black';
  for (let i = 0; i < mazeData.length; i++) {
    for (let j = 0; j < mazeData[i].length; j++) {
      if (mazeData[i][j] === 1) {
        ctx.fillRect(j * cellSize, i * cellSize, cellSize, cellSize);
      }
    }
  }

  // Draw bots
  for (const bot of bots) {
    ctx.beginPath();
    ctx.arc(bot.r * cellSize + cellSize / 2, bot.c * cellSize + cellSize / 2, cellSize / 4, 0, Math.PI * 2);
    ctx.fillStyle = 'blue'; // Distinct color for bots
    ctx.fill();
  }
}


function moveBot(bot) {
  const r = bot.r;
  const c = bot.c;

  const walls = [0, 1, 0, 1]; // e, s, w, n

  if (walls[0] === 1) { // West
    if (c > 0 && mazeData[r][c - 1] === 0) {
      bot.c--;
      bot.path.push({ r, c });
      return;
    }
  }
  if (walls[1] === 1) { // South
    if (r < mazeData.length - 1 && mazeData[r + 1][c] === 0) {
      bot.r++;
      bot.path.push({ r, c });
      return;
    }
  }
  if (walls[2] === 1) { // East
    if (c < mazeData[0].length - 1 && mazeData[r][c + 1] === 0) {
      bot.c++;
      bot.path.push({ r, c });
      return;
    }
  }
  if (walls[3] === 1) { // North
    if (r > 0 && mazeData[r - 1][c] === 0) {
      bot.r--;
      bot.path.push({ r, c });
      return;
    }
  }

  // Dead end detection and backtracking
  if (mazeData[r][c] === 1) { // If it hits a wall
    bot.deadEnds.push({ r, c });
  }

}


function tick() {
  if (!gameRunning) return;

  for (const bot of bots) {
    moveBot(bot);
  }

  drawMaze();

  // Check for completion
  for (const bot of bots) {
    if (bot.finishTick !== null) {
      completedCount++;
    }
  }


  if (completedCount === numBots) {
    clearInterval(intervalId);
    freezeTimer();
  }
}

function freezeTimer() {
  timer = window.game.elapsed; // Capture the elapsed time
}

function resetTimer() {
  timer = 0;
}



window.game = {
  tick: (n) => {
    for (let i = 0; i < n; i++) {
      tick();
    }
  },
  reset: (seed) => {
    initializeMaze();
  },
  elapsed: timer,
  size: { rows: mazeData.length, cols: mazeData[0].length },
  spawn: { r: 1, c: 1 },
  exit: { r: mazeData.length - 2, c: mazeData[0].length - 2 },
  walls: (r, c) => {
    return [
      mazeData[r][c] === 1,
      mazeData[r][c] === 1,
      mazeData[r][c] === 1,
      mazeData[r][c] === 1
    ];
  },
  bots: bots,
};

let intervalId = setInterval(tick, 20); // Tick every 20ms

document.getElementById('reset').addEventListener('click', () => {
  window.game.reset();
});

initializeMaze();
</script>
</body>
</html>
